"""
    write_synthetic_acquisition(path; cycles = 5, windows = 10, ms1_profile = false) -> path

Write a small version-66 acquisition file in the layout `open_acquisition` reads. It holds `cycles` cycles of one MS1
scan followed by `windows` MS2 scans with adjacent 10 m/z isolation windows from 400 m/z. MS1 scans hold isotope
envelopes of charge 2 and 3 (three peaks each); MS2 scans hold twelve fragment peaks. With `ms1_profile`, MS1 scans
are ion-trap profile-only scans (packet type 19): Gaussian peaks (FWHM 0.5) on a 0.125 m/z grid, and MS2 scans are
ion-trap centroid scans (packet type 18). Peaks are generated by `synthetic_ms1_peaks` and `synthetic_ms2_peaks`.
"""
function write_synthetic_acquisition(path::AbstractString; cycles::Int = 5, windows::Int = 10, ms1_profile::Bool = false)
    L = LAYOUT_V66
    b = UInt8[]
    function wr(k::Integer, x)
        v = reinterpret(UInt8, [htol(x)]); stop = k + length(v)
        length(b) < stop && append!(b, zeros(UInt8, stop - length(b)))
        b[k+1:stop] .= v
        nothing
    end
    align8(k) = cld(k, 8) * 8

    # file preamble and a one-entry device directory (entry offset filled in at the end)
    wr(0, PREAMBLE_MARKER); wr(VERSION_OFFSET, UInt32(66))
    dir = 0x400
    wr(dir - L.count_back, UInt32(1)); wr(dir - L.count_back + 4, UInt32(1))
    wr(dir, KIND_MASS_SPEC); wr(dir + 4, UInt32(0))

    # spectrum packets, in scan order
    p0 = 0x1000
    rows = NamedTuple[]
    k = p0; j = 0
    for c in 1:cycles, e in 0:windows
        j += 1
        rt = 1.0 + 0.01 * j
        if e == 0
            lo, hi = 350.0, 1500.0
            mz, it = synthetic_ms1_peaks(c)
            if ms1_profile
                A0, A1 = lo, 0.125; n = round(Int, (hi - lo) / A1) - 1
                pmz = [A0 + A1 * (q + 1) for q in 0:n-1]
                pit = Float32[sum(h * exp(-(m - x)^2 / (2 * (0.5 / 2.35482)^2)) for (x, h) in zip(mz, it)) for m in pmz]
                w1 = (24 + 8 + 4n) ÷ 4
                wr(k + PKT_W_PROFILE, UInt32(w1)); wr(k + PKT_W_PEAKS, UInt32(0))
                ps = k + PKT_HEADER
                wr(ps, A0); wr(ps + 8, A1); wr(ps + 16, UInt32(1)); wr(ps + 24, UInt32(0)); wr(ps + 28, UInt32(n))
                for q in 0:n-1; wr(ps + 32 + 4q, pit[q+1]); end
                m = argmax(pit)
                tic, bpi, bpm = sum(Float64, pit), Float64(pit[m]), pmz[m]
                type, size, analyser = 0x00000013, PKT_HEADER + 4w1, 0x00
            else
                type, size, analyser = 0x00000014, _write_centroids!(wr, k, mz, it), 0x04
                m = argmax(it); tic, bpi, bpm = sum(Float64, it), Float64(it[m]), Float64(mz[m])
            end
            push!(rows, (scan = j, cls = 0, order = 0x01, analyser = analyser, type = type, off = k - p0, size = size,
                         rt = rt, tic = tic, bpi = bpi, bpm = bpm, lo = lo, hi = hi, cycle = c, centre = NaN, width = NaN))
        else
            lo, hi = 150.0, 1200.0
            mz, it = synthetic_ms2_peaks(e)
            size = _write_centroids!(wr, k, mz, it); m = argmax(it)
            push!(rows, (scan = j, cls = e, order = 0x02, analyser = ms1_profile ? 0x00 : 0x04,
                         type = ms1_profile ? 0x00000012 : 0x00000014, off = k - p0, size = size, rt = rt,
                         tic = sum(Float64, it), bpi = Float64(it[m]), bpm = Float64(mz[m]), lo = lo, hi = hi, cycle = c,
                         centre = 395.0 + 10e, width = 10.0))
        end
        wr(k + PKT_LOW_MZ, Float32(lo)); wr(k + PKT_HIGH_MZ, Float32(hi))
        k += rows[end].size
    end
    n = length(rows)

    # scan table
    st = align8(k)
    for (q, r) in enumerate(rows)
        t = st + (q - 1) * L.scan_record
        wr(t + ST_INDEX, UInt32(q - 1)); wr(t + ST_MSCLASS, UInt32(r.cls)); wr(t + ST_SCAN, UInt32(r.scan))
        wr(t + ST_PKT_TYPE, UInt32(r.type)); wr(t + ST_PKT_SIZE, UInt32(r.size)); wr(t + ST_RT, r.rt)
        wr(t + ST_TIC, r.tic); wr(t + ST_BP_INT, r.bpi); wr(t + ST_BP_MZ, r.bpm)
        wr(t + ST_LOW_MZ, r.lo); wr(t + ST_HIGH_MZ, r.hi)
        wr(t + L.st_pkt_off, UInt64(r.off)); wr(t + L.st_cycle, UInt32(r.cycle))
    end

    # region C: one record per scan, directly after the scan table
    rc = st + n * L.scan_record
    wr(rc, UInt32(0)); x = rc + RC_LEAD
    for r in rows
        wr(x + RC_MS_ORDER, r.order); wr(x + RC_ANALYSER, r.analyser); x += L.rc_fixed
        if r.order == 0x02
            wr(x, UInt32(1)); wr(x + 4 + PE_CENTER, r.centre); wr(x + 4 + PE_WIDTH, r.width)
            wr(x + 4 + PE_ENERGY, 27.0); x += 4 + L.rc_prec
        else
            wr(x, UInt32(0)); x += 4
        end
        wr(x, UInt32(1)); wr(x + 4, r.lo); wr(x + 12, r.hi); x += 4 + RC_RANGE_SIZE
        wr(x, UInt32(0)); x += 4          # calibration coefficients
        wr(x, UInt32(0)); x += 4          # extra values
        wr(x + L.rc_tail - 1, 0x00); x += L.rc_tail
    end
    rd = x

    # mass-spec device block
    dev = align8(rd)
    wr(dev, DEVICE_BLOCK_SIGNATURE[1]); wr(dev + 4, DEVICE_BLOCK_SIGNATURE[2]); wr(dev + 8, DEVICE_BLOCK_SIGNATURE[3])
    wr(dev + DEV_FIRST_SCAN, UInt32(1)); wr(dev + DEV_LAST_SCAN, UInt32(n))
    wr(dev + DEV_FIRST_RT, rows[1].rt); wr(dev + DEV_LAST_RT, rows[end].rt)
    for (pos, v) in ((L.dev_scan_table, st), (L.dev_packet_start, p0), (L.dev_region_c, rc), (L.dev_region_d, rd),
                     (L.dev_region_a, rd), (L.dev_region_b, rd), (L.dev_self, dev))
        wr(dev + pos, UInt64(v))
    end
    wr(dev + L.dev_self + 64, UInt64(0))   # padding after the block
    wr(dir + 8, UInt64(dev))
    write(path, b)
    path
end

"""Centroid packet (W1 = 0, W2 = 1 + 2n) at `k`; returns the packet size in bytes."""
function _write_centroids!(wr, k, mz, it)
    n = length(mz)
    wr(k + PKT_W_PROFILE, UInt32(0)); wr(k + PKT_W_PEAKS, UInt32(1 + 2n))
    pk = k + PKT_HEADER; wr(pk, UInt32(n))
    for q in 0:n-1; wr(pk + 4 + 8q, mz[q+1]); wr(pk + 8 + 8q, it[q+1]); end
    PKT_HEADER + 4 * (1 + 2n)
end

"""MS1 peaks of synthetic cycle `c`: eight isotope envelopes (charge 2 and 3, three peaks each), sorted by m/z."""
function synthetic_ms1_peaks(c::Integer)
    mz = Float32[]; it = Float32[]
    for e in 0:7
        z = iseven(e) ? 2 : 3; mono = 420.0 + 60e + 0.0371c
        for q in 0:2
            push!(mz, Float32(mono + q * ISOTOPE_SPACING / z)); push!(it, Float32(1e6 * (1 + 0.1e) * (1.0, 0.8, 0.5)[q+1]))
        end
    end
    mz, it
end

"""MS2 peaks of synthetic window `w`: twelve fragments, sorted by m/z."""
synthetic_ms2_peaks(w::Integer) = (Float32[200 + 75q + 0.01w for q in 0:11], Float32[1e4 * (q + 1) for q in 0:11])
